/* Original watch silhouettes: decorative editorial illustrations, not SKMEI packshots. */
.am-budget-watch{
  pointer-events:none;position:absolute;z-index:0;right:11%;top:20%;
  display:block;width:clamp(58px,26%,115px);aspect-ratio:.87;
  border:clamp(7px,1vw,12px) solid #cdd7d0;border-radius:19%;
  background:radial-gradient(circle at 30% 20%,#445f65,#091c24 70%);
  box-shadow:inset 0 0 0 3px #586970,0 16px 27px #00182185,0 0 0 3px #cfd7d344;
  transform:rotate(-18deg);opacity:.87
}
.am-budget-watch::before,.am-budget-watch::after{
  content:"";position:absolute;z-index:-1;left:20%;width:60%;height:54%;
  border:3px solid #c4d1c7;background:linear-gradient(90deg,#294247,#667675 50%,#2c4346);
}
.am-budget-watch::before{bottom:98%;border-radius:12px 12px 0 0}
.am-budget-watch::after{top:98%;border-radius:0 0 12px 12px}
.am-budget-dial{position:absolute;inset:15%;display:block;border:2px solid #8eaaa2;border-radius:8px;background:
  linear-gradient(170deg,transparent 44%,#b5dad257 49%,transparent 54%),
  linear-gradient(#0c252b,#1c3940)}
.am-budget-dial::before{content:"12:45";position:absolute;inset:0;display:grid;place-items:center;color:#bddfcd;font:700 clamp(9px,1.2vw,15px)/1 monospace;letter-spacing:-.08em;text-shadow:0 0 7px #b0e4cb86}
.am-pick-retro .am-budget-watch{border-radius:9%;border-color:#e0c5a3;transform:rotate(-12deg)}
.am-pick-retro .am-budget-dial{border-radius:2px}
.am-pick-dress .am-budget-watch,.am-pick-steel .am-budget-watch{border-radius:50%;border-color:#cab280}
.am-pick-dress .am-budget-dial,.am-pick-steel .am-budget-dial{border-radius:50%}
.am-pick-dress .am-budget-dial::before,.am-pick-steel .am-budget-dial::before{content:"✦";font-family:Georgia,serif}
.am-pick-compact .am-budget-watch{border-radius:50%;border-color:#e4cbd8}
.am-pick-compact .am-budget-dial{border-radius:50%}
.am-pick-compact .am-budget-dial::before{content:"✦";font-family:Georgia,serif}
.am-extra-art .am-budget-watch-large{right:14%;top:19%;width:clamp(85px,31%,190px);border-width:12px;opacity:.75}
.am-pick-card .am-pick-visual-name,.am-pick-card .am-pick-visual-ref,.am-pick-card .am-pick-visual-caption,
.am-extra-art .am-extra-art-kicker,.am-extra-art .am-extra-art-brand,.am-extra-art .am-extra-art-model,.am-extra-art .am-extra-art-label{position:relative;z-index:1}
@media(max-width:570px){
  .am-pick-visual .am-budget-watch{right:13%;top:22%;width:76px;opacity:.62}
  .am-extra-art .am-budget-watch-large{right:15%;top:19%;width:100px;opacity:.52}
}
