.ud-art-fallback>span{font:700 12px system-ui;letter-spacing:.16em;text-transform:uppercase}
.ud-art-fallback strong{font:400 32px Georgia,serif;color:#fff}
.ud-art-fallback small{font:400 11px/1.6 system-ui,sans-serif}
